window.LD=window.LD||{};window.LD["party/p6"]={"id":"p6","name":"Cobalt Mercy","poss":"Cobalt Mercy's","members":["h19","h20"],"leader":"h19","morale":96,"disposition":"friendly","motto":"One falls, all turn back.","banner":{"c1":"#4caf50","c2":"#3c64c8","emblem":"lantern"},"loc":"ironhaven","loc_name":"Ironhaven","goal":{"text":"to earn 300 silver between them before the season ends","kind":"purse","done":76,"progress":"3,388 silver, past the 300 aimed for","missed":false,"crew":"Cobalt Mercy","party":"p6"},"vows":[{"text":"to die rich","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"Cobalt Mercy","party":"p6"}],"doing":"last seen on the road to Veldrock","progress":null,"today":["Coin between them: -251 silver (wagon 120, gear 68, rations 59).","Came away with 26 torches, 18 rations.","Wren: new gear, Fine Cloak."],"fights_today":[],"why":null,"founded_day":3,"founded_season":1,"disbanded":null,"anthem":null,"renown":290,"season":{"wins":13,"bosses":0,"floors":5,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30},"career":{"wins":30,"bosses":1,"floors":14,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":88},"former":[],"fallen":[],"travel":{"from":"ironhaven","to":"veldrock","left":1,"total":2,"dest":"emberdeep","counted":true},"wagon":{"kind":"covered_wagon","name":"Grand Duchess","label":"covered wagon","seats":4,"haul":45,"comfort":-1,"since":90,"desc":"A roof, a lantern, and somewhere dry to sleep.","moves":true,"puller":{"kind":"horse","name":"Clover","label":"riding horse","colour":"appaloosa","owner":null},"paid":[["Wren",116],["Barnaby",4]]},"pace_gap":0,"rels":[{"party":"p5","score":86},{"party":"p4","score":63},{"party":"p2","score":55}],"events":[{"id":"e122","day":3,"season":1,"sday":3,"kind":"party_formed","imp":4,"text":"Barnaby and Wren shake on it over a campfire in the Collapsed Mine: they are now Cobalt Mercy. (Friendly, by the look of them.)","heroes":["h19","h20"],"parties":["p6"],"loc":"collapsed_mine"},{"id":"e425","day":12,"season":1,"sday":12,"kind":"goal_done","imp":4,"text":"Cobalt Mercy can cross it off: earn 200 silver between them before the season ends. Drinks are on them. XP: Barnaby +800 (level 9!), Wren +800 (level 9!).","heroes":["h19","h20"],"parties":["p6"],"xp":{"h19":800,"h20":800}},{"id":"e578","day":17,"season":1,"sday":17,"kind":"boss","imp":5,"text":"Cobalt Mercy finishes off the Mimic King and a Kobold Slinger at the bottom of Cragtooth Warren and lives to tell of it. It was Barnaby's Steam Burst that dropped the kobold slinger. Battle Cry, from Wren, at exactly the right moment. Barnaby never left the leader's side. Loot: 106 silver each, 4 gems, 13 trinkets.","heroes":["h19","h20"],"parties":["p6"],"loc":"cragtooth_warren","fight":"f46","foes":["mimic_king","kobold_slinger"],"where":"at the bottom of Cragtooth Warren","won":true,"close":false,"shape":"plain","reworded":-31,"wx":"fog"},{"id":"e582","day":17,"season":1,"sday":17,"kind":"gear","imp":4,"text":"Out of Cragtooth Warren comes Barnaby, and with Barnaby comes a ring that feels faintly damp from the hoard hall: one of a kind, and not yet understood.","heroes":["h19","h20"],"parties":["p6"],"loc":"cragtooth_warren","wx":"fog"},{"id":"e598","day":17,"season":1,"sday":17,"kind":"big_move","imp":4,"text":"Cobalt Mercy finishes off the Mimic King and a Kobold Slinger at the bottom of Cragtooth Warren and lives to tell of it. On the table: Barnaby +91 renown (holds 1st) and Wren +85 (holds 2nd). Cobalt Mercy +130 party renown (3rd to 1st among the crews).","heroes":["h19","h20"],"parties":["p6"],"cause":"e578","moves":[{"hero":"h19","gain":91,"from":1,"to":1},{"hero":"h20","gain":85,"from":2,"to":2}],"party_moves":[{"party":"p6","gain":130,"from":3,"to":1}],"fight":"f46"},{"id":"e685","day":20,"season":1,"sday":20,"kind":"road","imp":2,"text":"Wren meets Lark for the first time looking over their shoulder, as they always do, and then back at Wren, as they never do.","heroes":["h20","h19"],"parties":["p6"],"road":"carrbridge~ironhaven","traveller":"lark","road_rec":"r154"},{"id":"e690","day":20,"season":1,"sday":20,"kind":"gift","imp":4,"text":"Wren has worn Delver's Lantern for a long time. Today it goes to Barnaby, who needs it more.","heroes":["h20","h19"],"parties":["p6"],"loc":"carrbridge"},{"id":"e718","day":21,"season":1,"sday":21,"kind":"road","imp":3,"text":"Ambrose Nimble deals Barnaby a hand for buttons. Barnaby wins, and is cheered by the sparrow on the nearest post.","heroes":["h19","h20"],"parties":["p6"],"road":"bleakmarsh~carrbridge","traveller":"nimble","road_rec":"r160"},{"id":"e775","day":22,"season":1,"sday":22,"kind":"talent","imp":2,"text":"Barnaby lights the campfire from across the clearing. And the next one over. Sorry, neighbours. Sunfall: one of the things Barnaby learned the long way round.","heroes":["h19"],"parties":["p6"],"loc":"thornmere_ruins","skill":"sunfall","wx":"fog"},{"id":"e778","day":22,"season":1,"sday":22,"kind":"boss_race","imp":3,"text":"The White Quills and Cobalt Mercy are headed for the same hole in the ground: Thornmere Ruins, where Mother Thornmere waits. Somebody is going to be disappointed.","heroes":["h7","h13","h19","h20"],"parties":["p5","p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e785","day":22,"season":1,"sday":22,"kind":"gift","imp":2,"text":"Wren admired Barnaby's Brooch from the Hill Cairn one too many times. Now it's Wren's.","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e801","day":23,"season":1,"sday":23,"kind":"delve","imp":1,"text":"Cobalt Mercy descends into Thornmere Ruins, untouched (0%).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e802","day":23,"season":1,"sday":23,"kind":"fight","imp":1,"text":"Cobalt Mercy, in fine spirits lately, makes short work of 3 Will-o'-Wisps in the gatehouse yard on floor 1 of Thornmere Ruins. Barnaby cleared three will-o'-wisps with a single Sunfall. Loot: 7 bottled wisplight, 7 wisp sugar. Barnaby, who has been afraid of deep water since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f56","foes":["wisp","wisp","wisp"],"where":"in the gatehouse yard on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"fog"},{"id":"e803","day":23,"season":1,"sday":23,"kind":"fight","imp":2,"text":"Three Bog Crawlers and a Will-o'-Wisp fall to Cobalt Mercy in the reed beds on floor 1 of Thornmere Ruins. That Sunfall from Barnaby was the moment it tipped. Ask the others what won it: Wren's Battle Cry. Loot: 4 chitin, 5 bog crawler claws, 2 bottled wisplight.","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f57","foes":["bog_crawler","bog_crawler","wisp"],"where":"in the reed beds on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":8,"wx":"fog"},{"id":"e804","day":23,"season":1,"sday":23,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Thornmere Ruins at a steady pace: 3 rooms (the gatehouse yard, the reed beds, the wayside cross).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"fog"},{"id":"e824","day":23,"season":1,"sday":23,"kind":"campfire","imp":1,"text":"Barnaby admits to being afraid of deep water. Wren doesn't laugh. Wren just nods and takes the watch nearest it.","heroes":["h20","h19"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e841","day":24,"season":1,"sday":24,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Thornmere Ruins at a push pace: 3 rooms (the pilgrims' hall, the causeway, the porters' lodge).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e842","day":24,"season":1,"sday":24,"kind":"talent","imp":1,"text":"Barnaby trims the Delver's Lantern's wick. Its golden light roams about, as if looking for something.","heroes":["h19"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e845","day":24,"season":1,"sday":24,"kind":"meet","imp":2,"text":"The White Quills and Cobalt Mercy share a fire in Thornmere Ruins. There is a short argument about the best road to Thornwall.","heroes":["h7","h13","h19","h20"],"parties":["p5","p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e862","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Thornmere Ruins at a cautious pace: 2 rooms (the scriptorium, the font that still fills).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e915","day":26,"season":1,"sday":26,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Thornmere Ruins at a push pace: 3 rooms (the buttery, the reliquary niche, the granary).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e938","day":27,"season":1,"sday":27,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 2 of Thornmere Ruins at a push pace: 3 rooms (the sacristy, the bell tower, the cloister walk).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"size":2,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e958","day":28,"season":1,"sday":28,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 2 of Thornmere Ruins at a push pace: 2 rooms (the bell tower's foundation stair, wet to the knee, The Lantern That Waits).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":2,"size":2,"floor":2,"traps":1,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e985","day":28,"season":1,"sday":28,"kind":"campfire","imp":3,"text":"It rains all day. Barnaby and Wren decide it is the other one's fault and are cheerful about it.","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e997","day":29,"season":1,"sday":29,"kind":"fight","imp":2,"text":"In the tithe barn on floor 2 of Thornmere Ruins, 3 Bog Crawlers get in Cobalt Mercy's way, briefly. Wren's Battle Cry had everyone hitting harder. Barnaby accounted for 3 of them, mostly with Sunfall. Loot: 5 chitin, 5 bog crawler claws.","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f67","foes":["bog_crawler","bog_crawler","bog_crawler"],"where":"in the tithe barn on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-17,"wx":"fog"},{"id":"e998","day":29,"season":1,"sday":29,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 3 of Thornmere Ruins at a push pace: 2 rooms (the reed maze, the tithe barn).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":2,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"fog"},{"id":"e1018","day":30,"season":1,"sday":30,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 3 of Thornmere Ruins at a cautious pace: 1 room (the refectory).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":1,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1019","day":30,"season":1,"sday":30,"kind":"delve_done","imp":3,"text":"Cobalt Mercy comes up for air after 8 days, pockets heavier and boots wetter. They got all the way to the bottom, found the buttery, the sacristy and The Lantern That Waits, mapped 44% of it, took the teeth out of 1 trap, cleared 19 rooms, came away with 67 silver between them and turned back because the rations would only just see them home. Add up every party's sketches and Thornmere Ruins comes out partly explored (50%).","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","days":8,"bottom":true,"rooms":["the buttery","the sacristy"],"gold":67,"turn":"supplies","wx":"fog"},{"id":"e1027","day":30,"season":1,"sday":30,"kind":"boss_race","imp":2,"text":"Cobalt Mercy gives up on Mother Thornmere for now, and the race to Thornmere Ruins belongs to The Lantern of Carrbridge and The Gravediggers of Ironhaven and The White Quills.","heroes":["h19","h20"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1028","day":30,"season":1,"sday":30,"kind":"meet","imp":1,"text":"The Gravediggers of Ironhaven run into Cobalt Mercy in Thornmere Ruins. Stories are exchanged, most of them exaggerated.","heroes":["h8","h15","h2","h11","h19","h20"],"parties":["p2","p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1049","day":30,"season":1,"sday":30,"kind":"season_end","imp":5,"text":"Season 1 ends. Wren is Hero of the Season with 288 renown. Cobalt Mercy finishes as the top party.","heroes":["h20","h19"],"parties":["p6"]},{"id":"e1050","day":30,"season":1,"sday":30,"kind":"top_party","imp":4,"text":"TOP PARTY: Cobalt Mercy (Barnaby and Wren) ends season 1 as the league's best crew, 365 party renown. Their season: 1 boss, 8 fights won and 7 floors explored.","heroes":["h19","h20"],"parties":["p6"]},{"id":"e1074","day":31,"season":2,"sday":1,"kind":"ability","imp":2,"text":"Wren haggles in Frosthold until the merchant laughs, gives up and pays 22 silver over the odds. Wren considers it a good afternoon's work.","heroes":["h20"],"parties":["p6"],"loc":"frosthold","skill":"head_for_figures","sk":"Head for Figures","rule":true,"wx":"snow"},{"id":"e1075","day":31,"season":2,"sday":1,"kind":"party_life","imp":1,"text":"By the third crossroads Barnaby has stopped waiting and started complaining about the wait.","heroes":["h19","h20"],"parties":["p6"],"loc":"frosthold","wx":"snow"},{"id":"e1092","day":31,"season":2,"sday":1,"kind":"talent","imp":1,"text":"Wren prices every cart that passes on the road, out loud.","heroes":["h20"],"parties":["p6"],"loc":"whitepeak","skill":"head_for_figures","wx":"snow"},{"id":"e1107","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Barnaby talks Wren through a bad night about being forgotten. Neither mentions it in the morning. Both remember.","heroes":["h19","h20"],"parties":["p6"],"loc":"whitepeak","wx":"snow"},{"id":"e1111","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from Cobalt Mercy: to die rich. Easy to say on day one.","heroes":["h19","h20"],"parties":["p6"]},{"id":"e1120","day":32,"season":2,"sday":2,"kind":"party_life","imp":1,"text":"Barnaby rides ahead, rides back, rides ahead again. Wren is not amused.","heroes":["h19","h20"],"parties":["p6"],"loc":"whitepeak","wx":"snow"},{"id":"e1154","day":33,"season":2,"sday":3,"kind":"delve","imp":1,"text":"Cobalt Mercy descends into Frostspire, untouched (0%).","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","wx":"snow"},{"id":"e1155","day":33,"season":2,"sday":3,"kind":"fight","imp":1,"text":"Cobalt Mercy defeats 2 Frost Wolves in the wolf run on floor 1 of Frostspire without much fuss. The last frost wolf turns tail. It was even until Barnaby's Sunfall. Then it wasn't. Without Wren's Oath of Light, this goes differently. Loot: 2 pelts, 6 fangs & claws.","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","fight":"f74","foes":["frost_wolf","frost_wolf"],"where":"in the wolf run on floor 1 of Frostspire","won":true,"close":false,"shape":"plain","reworded":-23,"wx":"snow"},{"id":"e1156","day":33,"season":2,"sday":3,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Frostspire at a steady pace: 3 rooms (the ice gate, the wolf run, the wrecked sledge).","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","pace":"steady","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":2,"wild":[]},"wx":"snow"},{"id":"e1169","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"Barnaby and Wren have shared a month of roads in Cobalt Mercy. Ask either one about the other and settle in for a story.","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","wx":"snow"},{"id":"e1170","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Wren writes a letter home by firelight and reads out the funny bits. The crew adds a postscript each.","heroes":["h20"],"parties":["p6"],"loc":"frostspire","skill":"letter_writer","wx":"snow"},{"id":"e1179","day":34,"season":2,"sday":4,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Frostspire at a steady pace: 2 rooms (the windbreak, the wind-scoured foot).","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e1194","day":34,"season":2,"sday":4,"kind":"campfire","imp":1,"text":"Wren and Barnaby start a running tally of who saved whom. It is currently tied, and disputed.","heroes":["h20","h19"],"parties":["p6"],"loc":"frostspire","wx":"snow"},{"id":"e1199","day":35,"season":2,"sday":5,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Frostspire at a steady pace: 2 rooms (the icicle porch, a hidden room behind the icicle porch).","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e1222","day":35,"season":2,"sday":5,"kind":"talent","imp":1,"text":"Barnaby lights a cavern so bright the bats file a complaint. Somebody asks how. 'Sunfall,' says Barnaby.","heroes":["h19"],"parties":["p6"],"loc":"frostspire","skill":"sunfall","wx":"snow"},{"id":"e1235","day":36,"season":2,"sday":6,"kind":"ambush","imp":2,"text":"Cobalt Mercy, in fine spirits lately, cuts down the Bounty Hunters' Captain and Bounty Hunter in Frostspire, sent for the price on Barnaby's head. Wren called Oath of Light, and the line steadied. Barnaby never stopped moving, start to finish. Wren gave the victory speech nobody asked for. Loot: 51 silver each, 10 stolen goods, 4 bandit sausages.","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","fight":"f82","foes":["bandit_captain","bandit"],"where":"in Frostspire, sent for the price on Barnaby's head","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"snow"},{"id":"e1236","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Frostspire at a steady pace: 2 rooms (the cairn of the turned-back, the giant's kitchen).","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"snow"},{"id":"e1237","day":36,"season":2,"sday":6,"kind":"ambush","imp":2,"text":"Cobalt Mercy wakes to a Yeti and an Ice Wraith in camp on floor 1 of Frostspire in the middle of the night, and beats them. The last yeti bolts. Wren's Battle Cry came at the right time for all of them. Barnaby landed the hit that turned it, then went straight back to guarding the packs. Loot: 4 ectoplasm, 2 frost crystals.","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","fight":"f83","foes":["yeti","ice_wraith"],"where":"at their camp on floor 1 of Frostspire, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-12,"wx":"snow"},{"id":"e1274","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Frostspire at a steady pace: 1 room (the buried trunks).","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e1275","day":37,"season":2,"sday":7,"kind":"delve_done","imp":3,"text":"Frostspire gives up Cobalt Mercy after 5 days, a little reluctantly, like a cat letting go of a sock. They got down to floor 1, came across the ice gate, the wrecked sledge, a hidden room behind the icicle porch and 1 more good room, took 10 rooms off the map's blank side, mapped 12% of it, split 168 silver on the way up and turned back because they were down to the last torch. Frostspire is mostly unexplored (11%), going by everyone's notes.","heroes":["h19","h20"],"parties":["p6"],"loc":"frostspire","days":5,"bottom":false,"rooms":["the ice gate","the wrecked sledge"],"gold":168,"turn":"dark","wx":"snow"},{"id":"e1364","day":39,"season":2,"sday":9,"kind":"party_life","imp":1,"text":"Wren arrives at camp an hour behind Barnaby and finds the good spot by the fire taken.","heroes":["h19","h20"],"parties":["p6"],"loc":"whitepeak","wx":"fog"},{"id":"e1367","day":39,"season":2,"sday":9,"kind":"ability","imp":2,"text":"Wren notices that the Frosthold buyer's scales lean a little. They say nothing and just look at them until the buyer adds 38 silver and a nervous smile.","heroes":["h20"],"parties":["p6"],"loc":"frosthold","skill":"head_for_figures","sk":"Head for Figures","rule":true,"wx":"fog"},{"id":"e1418","day":40,"season":2,"sday":10,"kind":"party_life","imp":1,"text":"Barnaby waits at every crossroads for Wren to catch up, and says nothing very loudly.","heroes":["h19","h20"],"parties":["p6"],"loc":"frosthold","wx":"snow"},{"id":"e1434","day":40,"season":2,"sday":10,"kind":"talent","imp":2,"text":"Barnaby melts a snowdrift off the mountain pass so the party can cross.","heroes":["h19"],"parties":["p6"],"loc":"frosthold","skill":"sunfall","wx":"snow"},{"id":"e1442","day":40,"season":2,"sday":10,"kind":"campfire","imp":1,"text":"Barnaby orders Wren an ale before Wren even sits down. Remembering an order is how it starts.","heroes":["h20","h19"],"parties":["p6"],"loc":"frosthold","wx":"snow"},{"id":"e1448","day":41,"season":2,"sday":11,"kind":"road","imp":3,"text":"Osk audits Wren's pack at the roadside, item by item, and finds everything in order, to his visible disappointment.","heroes":["h20","h19"],"parties":["p6"],"road":"frosthold~veldrock","traveller":"osk","road_rec":"r287"},{"id":"e1475","day":41,"season":2,"sday":11,"kind":"goal","imp":1,"text":"Cobalt Mercy sets their sights for the season: to win a town contest.","heroes":["h19","h20"],"parties":["p6"]},{"id":"e1486","day":42,"season":2,"sday":12,"kind":"road","imp":3,"text":"She tells Wren that the lamps near Cragtooth Warren flicker for no reason. Whatever it is, she has stopped going there.","heroes":["h20","h19"],"parties":["p6"],"road":"frosthold~veldrock","traveller":"hetty","road_rec":"r290"},{"id":"e1505","day":42,"season":2,"sday":12,"kind":"talent","imp":1,"text":"Veldrock asks Barnaby to light the midsummer bonfire. The stage will be rebuilt by autumn. Sunfall, the guild calls it.","heroes":["h19"],"parties":["p6"],"loc":"veldrock","skill":"sunfall","wx":"snow"},{"id":"e1532","day":43,"season":2,"sday":13,"kind":"gift","imp":2,"text":"Wren hands their old Lucky Traveler's Hat to Barnaby, who has been eyeing it for a week.","heroes":["h20","h19"],"parties":["p6"],"loc":"veldrock","wx":"storm"},{"id":"e1533","day":43,"season":2,"sday":13,"kind":"party_life","imp":1,"text":"Wren spends the whole road in the dust Barnaby kicks up, and says so.","heroes":["h19","h20"],"parties":["p6"],"loc":"veldrock","wx":"storm"},{"id":"e1534","day":43,"season":2,"sday":13,"kind":"road","imp":3,"text":"At a wayside shrine the Pilgrims dance their prayer round Wren and tie a ribbon on their pack for luck.","heroes":["h20","h19"],"parties":["p6"],"road":"saltmarrow~veldrock","traveller":"dancing_pilgrims","road_rec":"r298"},{"id":"e1543","day":43,"season":2,"sday":13,"kind":"talent","imp":2,"text":"Wren drafts a letter aloud while walking and Barnaby suggests cuts. Most of them are fair. Somebody asks how. 'Letter Writer,' says Wren.","heroes":["h20","h19"],"parties":["p6"],"loc":"veldrock","skill":"letter_writer","wx":"storm"},{"id":"e1549","day":43,"season":2,"sday":13,"kind":"campfire","imp":1,"text":"Wren stands in front of Barnaby when the arrows start. Barnaby notices.","heroes":["h20","h19"],"parties":["p6"],"loc":"veldrock","wx":"storm"},{"id":"e1551","day":43,"season":2,"sday":13,"kind":"goal_done","imp":4,"text":"GOAL: Cobalt Mercy set out to win a town contest, and they have done it, with 17 days to spare. It was Wren's idea in the first place. XP: Barnaby +960, Wren +960 (level 15!).","heroes":["h19","h20"],"parties":["p6"],"xp":{"h19":960,"h20":960}},{"id":"e1570","day":44,"season":2,"sday":14,"kind":"night_game","imp":2,"text":"The bandit has blocked the road for an hour on the road to Saltmarrow, waiting for somebody who plays Crooked Cards. Barnaby is the lucky one. Barnaby wins the last round, and the bandit stares at the table for a long moment before handing over Bandit's Marked Card. Wren laughs all the way on the road to Saltmarrow and then asks Barnaby to tell it again.","heroes":["h19","h20"],"parties":["p6"],"loc":"saltmarrow","night":"n82","monster_game":"bandit"},{"id":"e1571","day":44,"season":2,"sday":14,"kind":"road","imp":3,"text":"Brother Aldo is too ill to walk, so Wren shoulders the pack and most of the pilgrim as far as the next shelter.","heroes":["h20","h19"],"parties":["p6"],"road":"saltmarrow~veldrock","traveller":"aldo","road_rec":"r303"},{"id":"e1623","day":46,"season":2,"sday":16,"kind":"road","imp":3,"text":"Wren helps push a menagerie wagon out of a rut on the road to the Salt Cliffs, and the keeper shows them the star of the show: a small, grumpy, very real wyvern.","heroes":["h20","h19"],"parties":["p6"],"road":"saltcliffs~saltmarrow","road_rec":"r318"},{"id":"e1624","day":46,"season":2,"sday":16,"kind":"night","imp":2,"text":"Barnaby follows strange lights away from the camp in the Salt Cliffs, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h19","h20"],"parties":["p6"],"loc":"saltcliffs"},{"id":"e1663","day":47,"season":2,"sday":17,"kind":"night_game","imp":2,"text":"The siren does not charm anyone. She merely asks Barnaby, very prettily, to sit down for a round of Tide Cards. Barnaby blows the last hand and hands over 2 bundles of stolen goods. The siren promises to take good care of it all. Wren says it is a fine thing to be robbed by somebody who shakes your hand afterwards.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","night":"n88","monster_game":"siren"},{"id":"e1706","day":48,"season":2,"sday":18,"kind":"delve","imp":1,"text":"Cobalt Mercy descends into the Sunken Vault, untouched (0%).","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e1707","day":48,"season":2,"sday":18,"kind":"fight","imp":2,"text":"Cobalt Mercy gets the better of 2 Drowned and a Siren in the swallowed ship on floor 1 of the Sunken Vault. The Drowned spent the rest of the fight on fire, courtesy of Barnaby's Sunfall. Oath of Light did more for this fight than the scoreboard shows. That was Wren. Loot: 10 trinkets, 7 barnacle oysters, 4 remains. Barnaby, who has been afraid of deep water since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","fight":"f111","foes":["drowned","drowned","siren"],"where":"in the swallowed ship on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"plain","reworded":-11},{"id":"e1708","day":48,"season":2,"sday":18,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of the Sunken Vault at a steady pace: 2 rooms (the tide-gate, the swallowed ship).","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e1736","day":49,"season":2,"sday":19,"kind":"fight","imp":1,"text":"In the barnacled quay steps on floor 1 of the Sunken Vault, Cobalt Mercy squares up to 2 Cliff Crabs and carries the day. The last cliff crab takes off and isn't seen again. Everyone fought a little better after Wren's Oath of Light. Barnaby never once gave ground. Loot: 3 chitin, 2 fish.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","fight":"f112","foes":["crab","crab"],"where":"in the barnacled quay steps on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"place","reworded":-40},{"id":"e1737","day":49,"season":2,"sday":19,"kind":"fight","imp":3,"text":"Barnaby hits hardest as Cobalt Mercy beats 2 Drowned and a Cliff Crab in the gatehouse guardroom on floor 1 of the Sunken Vault. Steam Burst caught two of them in one go. That was Barnaby. Loot: 8 trinkets, 2 chitin, 4 barnacle oysters.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","fight":"f113","foes":["drowned","crab","drowned"],"where":"in the gatehouse guardroom on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"hero","reworded":-24},{"id":"e1738","day":49,"season":2,"sday":19,"kind":"gear","imp":3,"text":"In the gatehouse guardroom on floor 1 of the Sunken Vault, Wren finds Tidebound Fine Stilettos and puts them on. Salt-Hardened: tougher (+4% health). It is a step up from anything Wren could buy.","heroes":["h20"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e1739","day":49,"season":2,"sday":19,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of the Sunken Vault at a steady pace: 3 rooms (the barnacled quay steps, the undertow passage, the gatehouse guardroom).","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":1,"gear":["great"],"fears":3,"wild":[]}},{"id":"e1740","day":49,"season":2,"sday":19,"kind":"night","imp":2,"text":"A child turns up at Cobalt Mercy's camp on floor 1 of the Sunken Vault, announces that Frostspire \"eats lanterns\", and runs off before anyone can ask what that means.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e1756","day":49,"season":2,"sday":19,"kind":"campfire","imp":1,"text":"Barnaby buys Wren an ale. Then another. Then the conversation gets honest.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e1769","day":50,"season":2,"sday":20,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of the Sunken Vault at a steady pace: 2 rooms (the gate passage, the harbour-light stair).","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1784","day":50,"season":2,"sday":20,"kind":"campfire","imp":1,"text":"Wren lets Barnaby win at arm-wrestling. Barnaby knows, and both let it stand.","heroes":["h20","h19"],"parties":["p6"],"loc":"sunken_vault","wx":"fog"},{"id":"e1798","day":51,"season":2,"sday":21,"kind":"fight","imp":1,"text":"It's 2 Sirens against Cobalt Mercy in the exchange floor on floor 1 of the Sunken Vault, and it isn't close. The final blow was Barnaby's Alchemist's Fire. Oath of Light came over Wren at the right moment, as it does. Loot: 1 gem, 7 trinkets, 2 sea grapes.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","fight":"f118","foes":["siren","siren"],"where":"in the exchange floor on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"foe","reworded":-23},{"id":"e1800","day":51,"season":2,"sday":21,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of the Sunken Vault at a steady pace: 3 rooms (the scriveners' hall, the exchange floor, the clerks' desks).","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":1,"wild":[]}},{"id":"e1830","day":52,"season":2,"sday":22,"kind":"fight","imp":2,"text":"Cobalt Mercy, in fine spirits lately, sees off 2 Sea Serpents and a Cliff Crab in the sunken kitchens on floor 1 of the Sunken Vault. The fight ended in a flash of Barnaby's Spark Storm. Barnaby did the unglamorous work that kept the line from breaking. Loot: 4 chitin, 21 fangs & claws, 10 serpent fillets.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","fight":"f122","foes":["crab","sea_serpent","sea_serpent"],"where":"in the sunken kitchens on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1831","day":52,"season":2,"sday":22,"kind":"fight","imp":2,"text":"Cobalt Mercy dispatches a Siren and the Drowned in the depositors' queue on floor 1 of the Sunken Vault without much fuss. Wren finished the Drowned with Reckless Swing and leaned on their weapon, breathing hard. Loot: 1 gem, 11 trinkets, 5 remains.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","fight":"f123","foes":["siren","drowned"],"where":"in the depositors' queue on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e1832","day":52,"season":2,"sday":22,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of the Sunken Vault at a push pace: 4 rooms (the sunken kitchens, the assay room, the depositors' queue and 1 more).","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","pace":"push","stats":{"rooms":4,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["common"],"fears":3,"wild":[]}},{"id":"e1887","day":53,"season":2,"sday":23,"kind":"party_life","imp":3,"text":"Floor 1 was enough for Barnaby, who sat down cross-legged and asked to be collected on the way back. There was no way back without Barnaby, so Cobalt Mercy turns for the stairs.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","refusal":"h19"},{"id":"e1888","day":53,"season":2,"sday":23,"kind":"delve_done","imp":3,"text":"The Sunken Vault gives up Cobalt Mercy after 6 days, a little reluctantly, like a cat letting go of a sock. They got down to floor 1, inked 25% of the map, took 14 rooms off the map's blank side, turned up the gatehouse guardroom, the clerks' desks, the sunken kitchens and 1 more good room, split 106 silver on the way up and turned back when one of them would go no further. The Sunken Vault is mostly unexplored (17%), going by everyone's notes.","heroes":["h19","h20"],"parties":["p6"],"loc":"sunken_vault","days":6,"bottom":false,"rooms":["the gatehouse guardroom","the clerks' desks"],"gold":106,"turn":"refused"},{"id":"e1942","day":55,"season":2,"sday":25,"kind":"ability","imp":2,"text":"The Saltmarrow merchant offers a round number. Wren offers a less round one, with fractions. The merchant can't follow it, pays 22 silver extra to make it stop, and Wren leaves whistling.","heroes":["h20"],"parties":["p6"],"loc":"saltmarrow","skill":"head_for_figures","sk":"Head for Figures","rule":true},{"id":"e1965","day":55,"season":2,"sday":25,"kind":"big_move","imp":3,"text":"Wren has earned two thousand silver in the league. On the table: Wren +77 renown (14th to 10th). Cobalt Mercy +53 party renown (holds 5th among the crews).","heroes":["h20"],"parties":["p6"],"cause":"e1964","moves":[{"hero":"h20","gain":77,"from":14,"to":10}],"party_moves":[{"party":"p6","gain":53,"from":5,"to":5}]},{"id":"e1983","day":56,"season":2,"sday":26,"kind":"road","imp":3,"text":"Little Ansel wanders off after a butterfly and the whole procession halts. Wren finds the child at the edge of a field and carries Ansel back on their shoulders.","heroes":["h20","h19"],"parties":["p6"],"road":"saltmarrow~veldrock","traveller":"dancing_pilgrims","road_rec":"r386"},{"id":"e2001","day":56,"season":2,"sday":26,"kind":"campfire","imp":1,"text":"Wren patches Barnaby's cloak without being asked. Barnaby pretends not to notice, then says thanks.","heroes":["h19","h20"],"parties":["p6"],"loc":"saltmarrow"},{"id":"e2033","day":58,"season":2,"sday":28,"kind":"bounty","imp":2,"text":"Cobalt Mercy cashes in a season's worth of trophies at the Veldrock guild: about 101 silver a head.","heroes":["h19"],"parties":["p6"],"loc":"veldrock","amount":101},{"id":"e2076","day":59,"season":2,"sday":29,"kind":"road","imp":3,"text":"Mrs. Tench hands Wren a fish from that morning's catch, for the pot. Wren has been given a fish and a great deal of advice on cooking it.","heroes":["h20","h19"],"parties":["p6"],"road":"emberdeep~veldrock","traveller":"wet_boots","road_rec":"r405"},{"id":"e2110","day":60,"season":2,"sday":30,"kind":"tarot","imp":3,"text":"Barnaby lays three cards on a flat stone for Cobalt Mercy, with Emberdeep a short walk off in the dark: the Magician, the Hierophant and the Moon upside down. A good spread, all told.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","reading":"r417"},{"id":"e2115","day":60,"season":2,"sday":30,"kind":"campfire","imp":2,"text":"Barnaby and Wren trade war stories at the campfire until the fire burns down.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep"},{"id":"e2139","day":61,"season":3,"sday":1,"kind":"ability","imp":2,"text":"Wren totals the sale in Carrbridge twice in their head, finds the buyer's mistake, and collects 50 silver more. Very satisfying.","heroes":["h20"],"parties":["p6"],"loc":"carrbridge","skill":"head_for_figures","sk":"Head for Figures","rule":true},{"id":"e2140","day":61,"season":3,"sday":1,"kind":"road","imp":3,"text":"Prudence and Clementine are right here, Old Maudie says to Barnaby, but Tuesday has taken the chance to wander. A search begins.","heroes":["h19","h20"],"parties":["p6"],"road":"carrbridge~ironhaven","traveller":"maudie","road_rec":"r422"},{"id":"e2251","day":65,"season":3,"sday":5,"kind":"ambush","imp":2,"text":"Cobalt Mercy wakes to 2 Fire Elementals in camp in Emberdeep in the middle of the night, and defeats them. Wren picked out the fire elemental and finished the job with Reckless Swing. Barnaby saw every rush coming and shouted it in time. Wren kept the bleeding to a minimum. Loot: 9 living coals.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f151","foes":["fire_elemental","fire_elemental"],"where":"at their camp in Emberdeep, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-12,"wx":"storm"},{"id":"e2280","day":66,"season":3,"sday":6,"kind":"delve","imp":1,"text":"Cobalt Mercy descends into Emberdeep, untouched (0%).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep"},{"id":"e2283","day":66,"season":3,"sday":6,"kind":"fight","imp":2,"text":"In the hoard-slope on floor 1 of Emberdeep, Cobalt Mercy squares up to 2 Lava Golems and a Drake and carries the day. Barnaby's Flame Jet finished the fight. Loot: 2 ember cores, 43 ore, 1 drake scale.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f155","foes":["lava_golem","drake","lava_golem"],"where":"in the hoard-slope on floor 1 of Emberdeep","won":true,"close":false,"shape":"place","reworded":-25},{"id":"e2286","day":66,"season":3,"sday":6,"kind":"fight","imp":2,"text":"Two Salamanders make the mistake of going for Cobalt Mercy in the dwarven gatehouse on floor 1 of Emberdeep. Sunfall left Barnaby's hands and the salamander was done. Loot: 9 salamander tails.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f156","foes":["salamander","salamander"],"where":"in the dwarven gatehouse on floor 1 of Emberdeep","won":true,"close":false,"shape":"foe","reworded":-21},{"id":"e2287","day":66,"season":3,"sday":6,"kind":"fight","imp":2,"text":"Cobalt Mercy makes short work of 2 Lava Golems in the obsidian gallery on floor 1 of Emberdeep. Firebolt, from Barnaby, was the last thing the lava golem saw. Loot: 2 ember cores, 37 ore, 5 lava salt.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f157","foes":["lava_golem","lava_golem"],"where":"in the obsidian gallery on floor 1 of Emberdeep","won":true,"close":false,"shape":"plain"},{"id":"e2288","day":66,"season":3,"sday":6,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Emberdeep at a push pace: 4 rooms (the cold porch, the hoard-slope, the dwarven gatehouse and 1 more).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"push","stats":{"rooms":4,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":3,"close":1,"gear":["cosmetic"],"fears":2,"wild":[]}},{"id":"e2289","day":66,"season":3,"sday":6,"kind":"talent","imp":2,"text":"Wren takes Barnaby's turn on watch without being asked, and doesn't mention it in the morning.","heroes":["h20","h19"],"parties":["p6"],"loc":"emberdeep","skill":"almsgiver"},{"id":"e2305","day":66,"season":3,"sday":6,"kind":"talent","imp":1,"text":"Barnaby's little sun finds the way through a dark maze by drifting towards the draught.","heroes":["h19"],"parties":["p6"],"loc":"emberdeep","skill":"little_sun"},{"id":"e2315","day":67,"season":3,"sday":7,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Emberdeep at a cautious pace: 1 room (the ash slope).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"cautious","stats":{"rooms":1,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2316","day":67,"season":3,"sday":7,"kind":"talent","imp":1,"text":"Barnaby wakes up with an old ache gone and Wren pretending to be asleep.","heroes":["h20","h19"],"parties":["p6"],"loc":"emberdeep","skill":"living_saint"},{"id":"e2334","day":67,"season":3,"sday":7,"kind":"tarot","imp":2,"text":"Nobody sleeps until Barnaby has read for Cobalt Mercy. The night before Emberdeep, three cards: the Seven of Swords upside down, Strength and the Six of Pentacles upside down. Some good, some not.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","reading":"r462"},{"id":"e2355","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Emberdeep at a steady pace: 3 rooms (a walled-up room beside the ash slope, the smoking cleft, the hall of old kings).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"steady","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2356","day":68,"season":3,"sday":8,"kind":"talent","imp":1,"text":"Barnaby's little sun bobs over the tents all night like a nightlight. (Little Sun, if anyone's asking.)","heroes":["h19"],"parties":["p6"],"loc":"emberdeep","skill":"little_sun"},{"id":"e2397","day":69,"season":3,"sday":9,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Emberdeep at a steady pace: 2 rooms (the master smith's forge, the cairn of the unlucky).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common","common"],"fears":1,"wild":[]}},{"id":"e2415","day":69,"season":3,"sday":9,"kind":"campfire","imp":2,"text":"Barnaby shows Wren how to oil a scabbard properly. Wren pretends to know already, then takes notes.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep"},{"id":"e2425","day":70,"season":3,"sday":10,"kind":"fight","imp":2,"text":"Cobalt Mercy, in fine spirits lately, handles 2 Fire Elementals in the anvil rows on floor 1 of Emberdeep. Wren's Oath of Light had everyone hitting harder. Without Barnaby's Little Sun, this goes differently. Loot: 2 ember cores, 9 living coals.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f168","foes":["fire_elemental","fire_elemental"],"where":"in the anvil rows on floor 1 of Emberdeep","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"snow"},{"id":"e2426","day":70,"season":3,"sday":10,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Emberdeep at a steady pace: 2 rooms (the anvil rows, a chimney stair, soot on every tread).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"snow"},{"id":"e2427","day":70,"season":3,"sday":10,"kind":"talent","imp":1,"text":"Barnaby reads the tracks round camp at dawn: a fox, a badger, and Wren sleepwalking. Somebody asks how. 'Tracker,' says Barnaby.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","skill":"tracker","wx":"snow"},{"id":"e2443","day":70,"season":3,"sday":10,"kind":"talent","imp":1,"text":"Something undead takes one look at Wren and falls over on its own. Living Saint all the way, Wren insists.","heroes":["h20"],"parties":["p6"],"loc":"emberdeep","skill":"living_saint","wx":"snow"},{"id":"e2457","day":71,"season":3,"sday":11,"kind":"wild_room","imp":3,"text":"Barnaby took a corner in an ore cart in Emberdeep on two wheels, then on none. The corner was unharmed.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","room":"wild_ore_cart_run"},{"id":"e2458","day":71,"season":3,"sday":11,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 2 of Emberdeep at a push pace: 3 rooms (the ice cellar, the ore hoist, the ore track).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"push","stats":{"rooms":3,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_ore_cart_run"]}},{"id":"e2459","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"Wren tries to pet Barnaby's little sun. Wren has a bandage now, and a story. Little Sun: one of the things Barnaby learned the long way round.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","skill":"little_sun"},{"id":"e2486","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"Cobalt Mercy sets their sights for the season: to earn 300 silver between them before the season ends.","heroes":["h19","h20"],"parties":["p6"]},{"id":"e2512","day":72,"season":3,"sday":12,"kind":"fight","imp":2,"text":"Barnaby hits hardest as Cobalt Mercy beats 3 Fire Elementals in the dwarven great hall on floor 2 of Emberdeep. Ask anyone when it turned: Barnaby's Sunfall. Loot: 4 ember cores, 4 living coals.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f173","foes":["fire_elemental","fire_elemental","fire_elemental"],"where":"in the dwarven great hall on floor 2 of Emberdeep","won":true,"close":false,"shape":"hero","reworded":-24},{"id":"e2513","day":72,"season":3,"sday":12,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 2 of Emberdeep at a steady pace: 3 rooms (the clan crypt, the dwarven great hall, the dwarven bunk halls).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"steady","stats":{"rooms":3,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e2529","day":73,"season":3,"sday":13,"kind":"wild_room","imp":3,"text":"Barnaby read the runes on three dwarven casks in Emberdeep and picked the ale. The small print paid off.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","room":"wild_dwarven_toast","wx":"snow"},{"id":"e2530","day":73,"season":3,"sday":13,"kind":"fight","imp":2,"text":"A Drake and a Salamander fall to Cobalt Mercy in a chimney stair, soot on every tread on floor 2 of Emberdeep. Wren finished the salamander with Reckless Swing and leaned on their weapon, breathing hard. Loot: 1 drake scale.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f174","foes":["drake","salamander"],"where":"in a chimney stair, soot on every tread on floor 2 of Emberdeep","won":true,"close":false,"shape":"foe","reworded":1,"wx":"snow"},{"id":"e2531","day":73,"season":3,"sday":13,"kind":"fight","imp":2,"text":"In the ore stores on floor 2 of Emberdeep, Cobalt Mercy cuts down 3 Salamanders. Everything after Barnaby's Sunfall went right. Barnaby's Little Sun kicked in when it counted. Loot: 1 ember core, 4 salamander tails.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f175","foes":["salamander","salamander","salamander"],"where":"in the ore stores on floor 2 of Emberdeep","won":true,"close":false,"shape":"place","reworded":-1,"wx":"snow"},{"id":"e2532","day":73,"season":3,"sday":13,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 2 of Emberdeep at a push pace: 4 rooms (the sealed casks, a chimney stair, soot on every tread, the ore stores and 1 more).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"push","stats":{"rooms":4,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["common","common"],"fears":4,"wild":["wild_dwarven_toast"]},"wx":"snow"},{"id":"e2533","day":73,"season":3,"sday":13,"kind":"night","imp":2,"text":"Wren's ghost story on floor 2 of Emberdeep goes on too long and never really ends. Barnaby lies awake waiting for the ending.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","wx":"snow"},{"id":"e2566","day":74,"season":3,"sday":14,"kind":"delve_done","imp":3,"text":"Emberdeep gives up Cobalt Mercy after 9 days, a little reluctantly, like a cat letting go of a sock. They reached floor 2, put 30% of it on paper, cleared 22 rooms, found the obsidian gallery, a walled-up room beside the ash slope, the master smith's forge and 5 more good rooms, came away with 142 silver between them and turned back because their nerves were fraying. The guild's map has it: Emberdeep is mostly unexplored (25%).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","days":9,"bottom":false,"rooms":["the obsidian gallery","a walled-up room beside the ash slope"],"gold":142,"turn":"nerve","wx":"snow"},{"id":"e2601","day":75,"season":3,"sday":15,"kind":"road","imp":3,"text":"Under a bridge on the road to Veldrock sits a very large person who asks a toll in compliments. Barnaby offers three good ones, and the large person weeps with joy and lifts the bar.","heroes":["h19","h20"],"parties":["p6"],"road":"emberdeep~veldrock","road_rec":"r504"},{"id":"e2637","day":76,"season":3,"sday":16,"kind":"bounty","imp":2,"text":"Cobalt Mercy cashes in a season's worth of trophies at the Veldrock guild: about 214 silver a head.","heroes":["h19"],"parties":["p6"],"loc":"veldrock","amount":214},{"id":"e2639","day":76,"season":3,"sday":16,"kind":"ability","imp":2,"text":"The Veldrock buyer names a price. Wren names another, then shows the working. The buyer sighs and adds 45 silver. Wren hums all the way out.","heroes":["h20"],"parties":["p6"],"loc":"veldrock","skill":"head_for_figures","sk":"Head for Figures","rule":true},{"id":"e2662","day":76,"season":3,"sday":16,"kind":"vow_progress","imp":3,"text":"Cobalt Mercy swore to die rich on day 1 of season 2. With 3,473 silver earned since, they're rich. Now they just have to stay that way until the age ends.","heroes":["h19","h20"],"parties":["p6"],"cause":"e1111"},{"id":"e2664","day":76,"season":3,"sday":16,"kind":"goal_done","imp":4,"text":"Cobalt Mercy can cross it off: earn 300 silver between them before the season ends. Drinks are on them. XP: Barnaby +960, Wren +960.","heroes":["h19","h20"],"parties":["p6"],"xp":{"h19":960,"h20":960}},{"id":"e2665","day":76,"season":3,"sday":16,"kind":"big_move","imp":4,"text":"Cobalt Mercy can cross it off: earn 300 silver between them before the season ends. On the table: Barnaby +55 renown (18th to 9th) and Wren +52 (15th to 8th). Cobalt Mercy +53 party renown (6th to 4th among the crews).","heroes":["h19","h20"],"parties":["p6"],"cause":"e2664","moves":[{"hero":"h19","gain":55,"from":18,"to":9},{"hero":"h20","gain":52,"from":15,"to":8}],"party_moves":[{"party":"p6","gain":53,"from":6,"to":4}]},{"id":"e2686","day":77,"season":3,"sday":17,"kind":"boss_race","imp":3,"text":"Cindervast the Hoardmother has visitors coming. The Gravediggers of Ironhaven and Cobalt Mercy are both on the way to Emberdeep, and nobody is waiting for the others.","heroes":["h8","h15","h2","h11","h19","h20"],"parties":["p2","p6"],"loc":"emberdeep"},{"id":"e2720","day":78,"season":3,"sday":18,"kind":"road","imp":2,"text":"Wren shares their rations at the Pitmen's Rest with a hungry miner, and is paid back with a lump of good ore and the tale of its finding.","heroes":["h20","h19"],"parties":["p6"],"road":"emberdeep~veldrock","road_rec":"r533"},{"id":"e2741","day":79,"season":3,"sday":19,"kind":"delve","imp":1,"text":"Cobalt Mercy descends into Emberdeep, mostly unexplored (25%), map in hand.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","wx":"storm"},{"id":"e2742","day":79,"season":3,"sday":19,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 1 of Emberdeep at a push pace: 2 rooms (the rune-lock treasury door, the ore hoist).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"push","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e2745","day":79,"season":3,"sday":19,"kind":"meet","imp":2,"text":"Sela and Wren swap stories in Emberdeep while The Gravediggers of Ironhaven and Cobalt Mercy swap rumours.","heroes":["h8","h15","h2","h11","h19","h20"],"parties":["p2","p6"],"loc":"emberdeep","wx":"storm"},{"id":"e2767","day":80,"season":3,"sday":20,"kind":"fight","imp":2,"text":"Cobalt Mercy runs into 4 Fire Elementals in the casting floor on floor 1 of Emberdeep and comes out on top. One Alchemist's Fire from Barnaby and two fire elementals were on the ground. Wren's Oath of Light turned the fight. Loot: 7 ember cores.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f185","foes":["fire_elemental","fire_elemental","fire_elemental"],"where":"in the casting floor on floor 1 of Emberdeep","won":true,"close":false,"shape":"plain","reworded":-20,"wx":"storm"},{"id":"e2768","day":80,"season":3,"sday":20,"kind":"gear","imp":1,"text":"In the dwarven brewery on floor 2 of Emberdeep, Barnaby finds a Sturdy Champion's Belt and puts it on. Sturdy: a little better protected (+1.5 armour).","heroes":["h19"],"parties":["p6"],"loc":"emberdeep","wx":"storm"},{"id":"e2769","day":80,"season":3,"sday":20,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 2 of Emberdeep at a push pace: 3 rooms (a sealed space off the falcon's shaft, the casting floor, the dwarven brewery).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"push","stats":{"rooms":3,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":1,"gear":["great"],"fears":0,"wild":[]},"wx":"storm"},{"id":"e2770","day":80,"season":3,"sday":20,"kind":"ambush","imp":2,"text":"In the middle of the night, 2 Fire Elementals find Cobalt Mercy's camp on floor 2 of Emberdeep, and Cobalt Mercy makes short work of them. The fire elemental had been trouble right up until Barnaby's Sunfall. Wren kept everyone standing (128 healed, Prayer of Healing doing the heavy lifting). Barnaby fought with Nana the way her grandmother taught her. \"Next,\" says Barnaby. Loot: 2 ember cores, 9 living coals.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f186","foes":["fire_elemental","fire_elemental"],"where":"at their camp on floor 2 of Emberdeep, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-21,"wx":"storm"},{"id":"e2803","day":81,"season":3,"sday":21,"kind":"fight","imp":2,"text":"Cobalt Mercy, in fine spirits lately, makes short work of 2 Fire Elementals and a Salamander in the dwarven great hall on floor 2 of Emberdeep. Everyone fought a little better after Wren's Oath of Light. Little Sun came over Barnaby at the right moment, as it does. Loot: 6 ember cores, 1 drake scale, 4 salamander tails.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f189","foes":["salamander","fire_elemental","fire_elemental"],"where":"in the dwarven great hall on floor 2 of Emberdeep","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"storm"},{"id":"e2804","day":81,"season":3,"sday":21,"kind":"fight","imp":2,"text":"Barnaby hits hardest as Cobalt Mercy dispatches a Fire Elemental and a Salamander in the guest lodge on floor 2 of Emberdeep. Barnaby landed Little Sun on the fire elemental hard enough to hear from the back. Loot: 2 ember cores. Injured: Barnaby (concussion).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f190","foes":["fire_elemental","salamander"],"where":"in the guest lodge on floor 2 of Emberdeep","won":true,"close":false,"shape":"hero","reworded":-24,"wx":"storm"},{"id":"e2805","day":81,"season":3,"sday":21,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 2 of Emberdeep at a steady pace: 3 rooms (the dwarven great hall, the bellows hall, the guest lodge).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"steady","stats":{"rooms":3,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"storm"},{"id":"e2843","day":82,"season":3,"sday":22,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 3 of Emberdeep at a steady pace: 2 rooms (the last watch, the mint vault).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"steady","stats":{"rooms":2,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":1,"wild":[]},"wx":"storm"},{"id":"e2844","day":82,"season":3,"sday":22,"kind":"talent","imp":2,"text":"Barnaby lights the campfire from across the clearing. And the next one over. Sorry, neighbours. Barnaby puts it down to Sunfall.","heroes":["h19"],"parties":["p6"],"loc":"emberdeep","skill":"sunfall","wx":"storm"},{"id":"e2858","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Wren teaches Barnaby how to haggle. Barnaby practises on the fire. Head for Figures, the guild calls it.","heroes":["h20","h19"],"parties":["p6"],"loc":"emberdeep","skill":"head_for_figures","wx":"storm"},{"id":"e2879","day":83,"season":3,"sday":23,"kind":"fight","imp":2,"text":"In the salamanders' audience pool on floor 3 of Emberdeep, 3 Salamanders get in Cobalt Mercy's way, briefly. Sunfall caught three salamanders in one go. That was Barnaby. Loot: 9 salamander tails.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","fight":"f197","foes":["salamander","salamander","salamander"],"where":"in the salamanders' audience pool on floor 3 of Emberdeep","won":true,"close":false,"shape":"place","reworded":-15,"wx":"storm"},{"id":"e2880","day":83,"season":3,"sday":23,"kind":"wild_room","imp":3,"text":"Barnaby and Wren failed to turn two keys at once in Emberdeep. Each blames the other's counting.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","room":"wild_two_key_strongroom","wx":"storm"},{"id":"e2881","day":83,"season":3,"sday":23,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 3 of Emberdeep at a push pace: 3 rooms (the salamander pools, a sealed space off the salamanders' audience pool, the two-key strongroom).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"push","stats":{"rooms":3,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":4,"wild":["wild_two_key_strongroom"]},"wx":"storm"},{"id":"e2917","day":84,"season":3,"sday":24,"kind":"delve_day","imp":1,"text":"Cobalt Mercy works floor 3 of Emberdeep at a steady pace: 2 rooms (the charcoal store, The Dragon's Breath).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","pace":"steady","stats":{"rooms":2,"size":2,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"snow"},{"id":"e2955","day":85,"season":3,"sday":25,"kind":"delve_done","imp":3,"text":"Up the last steps after 7 days: Cobalt Mercy climbs into the sun and nobody says anything for a while. They got down to floor 3, inked 45% of the map, cleared 15 rooms, turned up the rune-lock treasury door, a sealed space off the falcon's shaft, the dwarven brewery and 6 more good rooms, split 354 silver on the way up and turned back because their nerves were fraying. Emberdeep, all crews together: partly explored (43%).","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","days":7,"bottom":false,"rooms":["the rune-lock treasury door","a sealed space off the falcon's shaft"],"gold":354,"turn":"nerve","wx":"snow"},{"id":"e2956","day":85,"season":3,"sday":25,"kind":"night","imp":1,"text":"Wren tells a ghost story by the fire outside Emberdeep. Barnaby sleeps with a hand on her weapon.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","wx":"snow"},{"id":"e2974","day":85,"season":3,"sday":25,"kind":"campfire","imp":1,"text":"Barnaby teaches Wren a card game. Wren wins every hand after the first.","heroes":["h19","h20"],"parties":["p6"],"loc":"emberdeep","wx":"snow"},{"id":"e2995","day":86,"season":3,"sday":26,"kind":"road","imp":3,"text":"The water in the Pitmen's Rest barrel trembles in rings, once, twice, and the miners all look at the floor and then at each other. Barnaby files it away.","heroes":["h19","h20"],"parties":["p6"],"road":"emberdeep~veldrock","road_rec":"r585"},{"id":"e3010","day":86,"season":3,"sday":26,"kind":"campfire","imp":3,"text":"Wren wraps Barnaby's sore wrist tighter than strictly needed and tuts the whole time.","heroes":["h20","h19"],"parties":["p6"],"loc":"emberdeep"},{"id":"e3018","day":87,"season":3,"sday":27,"kind":"road","imp":3,"text":"Little Dill whispers to Wren that Eustace's pike has been seen near the Sunken Vault, and that nobody has dared go and look since.","heroes":["h20","h19"],"parties":["p6"],"road":"emberdeep~veldrock","traveller":"wet_boots","road_rec":"r586"},{"id":"e3020","day":87,"season":3,"sday":27,"kind":"bounty","imp":2,"text":"The guild clerk in Veldrock counts out bounties for Cobalt Mercy until the cashbox is empty: 165 silver each.","heroes":["h19"],"parties":["p6"],"loc":"veldrock","amount":165},{"id":"e3024","day":87,"season":3,"sday":27,"kind":"ability","imp":2,"text":"Wren sells the haul in Veldrock one piece at a time instead of by the sack, and the difference comes to 20 silver. They write it down twice, for the pleasure of it.","heroes":["h20"],"parties":["p6"],"loc":"veldrock","skill":"head_for_figures","sk":"Head for Figures","rule":true},{"id":"e3039","day":87,"season":3,"sday":27,"kind":"talent","imp":1,"text":"Barnaby rolls a blank, declares it 'a seven, technically', and is shouted down by the whole table.","heroes":["h19"],"parties":["p6"],"loc":"veldrock"},{"id":"e3143","day":90,"season":3,"sday":30,"kind":"wagon","imp":3,"text":"Cobalt Mercy rolls out of Ironhaven in a covered wagon called Grand Duchess, 120 silver between them. Who paid: Wren 116, Barnaby 4.","heroes":["h19","h20"],"parties":["p6"],"loc":"ironhaven"},{"id":"e3144","day":90,"season":3,"sday":30,"kind":"road","imp":2,"text":"Wren finds Sergeant Hobb Withy for the first time sitting on a milestone, polishing a button with great care and unseen devotion.","heroes":["h20","h19"],"parties":["p6"],"road":"ironhaven~veldrock","traveller":"withy","road_rec":"r614"},{"id":"e3168","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Lantern of Carrbridge, to die rich (sworn in season 2); Azure Edge, never to pay a toll (sworn in season 1); The Tidal Almanac, never to retreat (sworn in season 2); The Tidal Almanac, to die rich (sworn in season 2); The White Quills, to keep the peace: never draw first on another hero (sworn in season 1); Cobalt Mercy, to die rich (sworn in season 2); Tobias, never to pay a toll (sworn in season 2); Juniper, never to retreat (sworn in season 1). Every one of them held.","heroes":["h10","h6"],"parties":["p1","p3","p4","p5","p6"]}],"roles":{"h19":"Leader · Spellcaster","h20":"Quartermaster"},"quest":{"what":"Delve","where":"Emberdeep","why":"after the boss: about 102 silver a day each, risk slight; Wren's last chance at the dream before the age ends","floor":0,"floors":4},"tactics":{"front":["h20"],"back":["h19"],"plan":"Wren holds the front; Barnaby casts from behind; Wren keeps everyone standing.","traits":{"boldness":0.09,"risk":0.45,"greed":0.07,"sociability":0.17,"honor":-0.11,"curiosity":-0.25,"temper":-0.15,"loyalty":0.66},"mix":"1 caster, 1 blade","notes":[],"style":["reckless","mixed"],"skills":[{"label":"Damage","skills":[{"hero":"h19","id":"sunfall","name":"Sunfall","desc":"Brings down a small piece of the sun. Aims it, roughly.","tags":[],"rank":1,"uses":25},{"hero":"h19","id":"firebolt","name":"Firebolt","desc":"The classic.","tags":["fire"],"rank":2,"uses":10},{"hero":"h20","id":"reckless_swing","name":"Reckless Swing","desc":"All in. Every time.","tags":["rage"],"rank":1,"uses":9},{"hero":"h19","id":"alchemists_fire","name":"Alchemist's Fire","desc":"A clay jar with strong opinions.","tags":["craft","fire"],"rank":2,"uses":7},{"hero":"h19","id":"steam_burst","name":"Steam Burst","desc":"Fire meets ice. Everyone gets a facial.","tags":["fire","ice"],"rank":2,"uses":3},{"hero":"h19","id":"spark_storm","name":"Spark Storm","desc":"Showy. Effective. Smells of ozone.","tags":["storm","fire"],"rank":1,"uses":3},{"hero":"h19","id":"flame_jet","name":"Flame Jet","desc":"Two quick gouts from the fingertips.","tags":["fire"],"rank":3,"uses":3},{"hero":"h20","id":"hammer_down","name":"Hammer Down","desc":"Forging technique, applied to faces.","tags":["craft"],"rank":1,"uses":3},{"hero":"h20","id":"radiance","name":"Radiance","desc":"A flash of holy light, right in the eyes.","tags":["holy"],"rank":2,"uses":2},{"hero":"h19","id":"meteor","name":"Meteor","desc":"Calls down the sky.","tags":["fire"],"rank":1,"uses":0},{"hero":"h20","id":"pan_to_the_face","name":"Pan to the Face","desc":"The frying pan was for cooking. Was.","tags":[],"rank":1,"uses":0}]},{"label":"Healing","skills":[{"hero":"h20","id":"prayer_of_healing","name":"Prayer of Healing","desc":"Everybody, bow your heads.","tags":["holy","heal"],"rank":1,"uses":7},{"hero":"h20","id":"miracle","name":"Miracle","desc":"Witnesses still argue about what they saw.","tags":["holy","heal"],"rank":1,"uses":4}]},{"label":"Defence","skills":[{"hero":"h20","id":"battle_cry","name":"Battle Cry","desc":"Bellows something inspiring and mostly vowels. Everyone swings harder.","tags":["command","rage"],"rank":2,"uses":13},{"hero":"h19","id":"arcane_shield","name":"Arcane Shield","desc":"A shimmer over the whole party.","tags":["arcane","guard"],"rank":2,"uses":6}]},{"label":"Tricks","skills":[{"hero":"h20","id":"oath_of_light","name":"Oath of Light","desc":"Says the oath before the first blow. The oath is long. The armour holds.","tags":["holy"],"rank":3,"uses":22},{"hero":"h19","id":"little_sun","name":"Little Sun","desc":"Brought a tiny piece of the sun home. It follows them about.","tags":[],"rank":1,"uses":11},{"hero":"h19","id":"cold_snap","name":"Cold Snap","desc":"The temperature drops ten degrees, on purpose.","tags":["ice"],"rank":1,"uses":3},{"hero":"h20","id":"living_saint","name":"Living Saint","desc":"Small miracles, daily. Paperwork, endless.","tags":[],"rank":1,"uses":3}]},{"label":"Always on","skills":[{"hero":"h19","id":"combustion","name":"Combustion","desc":"Everything burns hotter.","tags":["fire"],"rank":2,"uses":0},{"hero":"h19","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0},{"hero":"h20","id":"spiked_shield","name":"Spiked Shield","desc":"Bolted a few spikes on. Improved the conversation.","tags":["craft","guard"],"rank":2,"uses":0},{"hero":"h20","id":"steady_nerves","name":"Steady Nerves","desc":"Doesn't flinch. Neither does the party.","tags":["holy"],"rank":2,"uses":0},{"hero":"h20","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h19","id":"weather_eye","name":"Weather Eye","desc":"Smells rain two hours off.","tags":["storm"],"rank":1,"uses":0},{"hero":"h19","id":"bonfire_night","name":"Bonfire Night","desc":"Lights a bonfire on the green. Half the town turns up; one stays.","tags":["fire"],"rank":2,"uses":0},{"hero":"h19","id":"fire_watch","name":"Fire Watch","desc":"Sleeps beside the fire. Wakes before the wolves do.","tags":["fire"],"rank":2,"uses":0},{"hero":"h19","id":"tracker","name":"Tracker","desc":"Reads a broken twig like a letter.","tags":["nature","beast"],"rank":1,"uses":0},{"hero":"h19","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0},{"hero":"h19","id":"lightning_rod","name":"Lightning Rod","desc":"Draws the strike on storm nights and sells the glass.","tags":["storm"],"rank":1,"uses":0},{"hero":"h20","id":"almsgiver","name":"Almsgiver","desc":"Never passes a beggar's bowl.","tags":["holy"],"rank":1,"uses":0},{"hero":"h20","id":"bulk_trader","name":"Bulk Trader","desc":"Buys a mule. Then another.","tags":["trade","travel"],"rank":1,"uses":0},{"hero":"h20","id":"market_gossip","name":"Market Gossip","desc":"Knows what pepper costs in three towns.","tags":["trade"],"rank":1,"uses":0},{"hero":"h20","id":"forgery","name":"Forgery","desc":"Their handwriting is your handwriting.","tags":["stealth","trade"],"rank":2,"uses":0},{"hero":"h20","id":"devout","name":"Devout","desc":"Temples patch them up for less.","tags":["holy"],"rank":1,"uses":0},{"hero":"h20","id":"letter_writer","name":"Letter Writer","desc":"Writes home. Writes everyone's home.","tags":["lore"],"rank":1,"uses":0},{"hero":"h20","id":"brewer","name":"Brewer","desc":"Every camp has a bubbling pot that isn't soup.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h19","dmg":9643,"healed":0,"taken":749,"kills":28,"row":"back"},{"hero":"h20","dmg":953,"healed":978,"taken":966,"kills":2,"row":"front"}],"ground":{"name":"Emberdeep","fights":13}},"trophies":[{"boss":"The Mimic King","monster":"mimic_king","place":"Cragtooth Warren","day":17,"season":1,"fight":"f46"}]};